// Post-hoc honesty audit: citations present + abstention honored (plain JS)
function auditAnswer(answer, sources) {
  const issues = [];
  if (answer.cites) {
    for (const c of answer.cites) {
      const found = sources.some((s) => s.includes(c.quote));
      if (!found) issues.push(`uncited claim: ${c.claim}`);
    }
  } else if (answer.text && !answer.unknown) {
    issues.push("specifics without citations");
  }
  if (answer.unknown && answer.text) issues.push("abstained yet answered");
  return { honest: issues.length === 0, issues };
}
